static SERVICE: VariantService = VariantService;

fn run_ready<F: std::future::Future>(future: F) -> F::Output {
    let mut future = pin!(future);
    let mut context = Context::from_waker(Waker::noop());
    match future.as_mut().poll(&mut context) {
        Poll::Ready(output) => output,
        Poll::Pending => panic!("the generated route fixture must be immediately ready"),
    }
}

fn observe<B>(body: B) -> (usize, u64)
where
    B: HttpBody<Data = Bytes>,
    B::Error: std::fmt::Debug,
{
    let mut body = pin!(body);
    let mut context = Context::from_waker(Waker::noop());
    let mut length = 0;
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    loop {
        match body.as_mut().poll_frame(&mut context) {
            Poll::Ready(Some(Ok(frame))) => {
                if let Ok(data) = frame.into_data() {
                    length += data.len();
                    for byte in data {
                        hash ^= u64::from(byte);
                        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
                    }
                }
            }
            Poll::Ready(Some(Err(error))) => panic!("fixture body failed: {error:?}"),
            Poll::Ready(None) => return (length, hash),
            Poll::Pending => panic!("the generated body fixture must be immediately ready"),
        }
    }
}

fn main() {
    let path = std::hint::black_box("/variants/route-127");
    let mut request = Request::new(());
    *request.uri_mut() = path.parse().expect("the generated fixture path is a valid URI");
    let response = run_ready(SERVICE.route(request, &()));
    let status = response.status().as_u16();
    std::hint::black_box((status, observe(response.into_body())));
}
